#requires -Version 5.1
[CmdletBinding()]param([string]$Path='C:\',[int]$Top=50,[switch]$IncludeUserProfiles)
$root='C:\ProgramData\BlueRidge\DiskReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "disk-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'disk-space-investigator.log') -Append|Out-Null
try{Get-Volume|Where DriveLetter|Select DriveLetter,FileSystemLabel,FileSystem,HealthStatus,@{n='SizeGB';e={[math]::Round($_.Size/1GB,2)}},@{n='FreeGB';e={[math]::Round($_.SizeRemaining/1GB,2)}},@{n='FreePercent';e={if($_.Size){[math]::Round(($_.SizeRemaining/$_.Size)*100,1)}}}|Export-Csv (Join-Path $d volumes.csv) -NoTypeInformation;$files=Get-ChildItem -LiteralPath $Path -File -Recurse -Force -ErrorAction SilentlyContinue|Sort Length -Descending|Select -First $Top FullName,@{n='SizeGB';e={[math]::Round($_.Length/1GB,3)}},LastWriteTime;$files|Export-Csv (Join-Path $d largest-files.csv) -NoTypeInformation;if($IncludeUserProfiles){Get-ChildItem C:\Users -Directory -Force -ErrorAction SilentlyContinue|ForEach-Object{$sum=(Get-ChildItem $_.FullName -File -Recurse -Force -ErrorAction SilentlyContinue|Measure Length -Sum).Sum;[pscustomobject]@{Profile=$_.FullName;SizeGB=[math]::Round($sum/1GB,2)}}|Sort SizeGB -Descending|Export-Csv (Join-Path $d profile-sizes.csv) -NoTypeInformation};Write-Host "Disk report: $d" -ForegroundColor Green;Write-Warning 'This script reports only; it does not delete files.'}finally{Stop-Transcript|Out-Null}
